{
  "name": "rf_channel_update_descriptor",
  "confidence": "medium",
  "docstring": "Updates an RF channel descriptor with 2.4 GHz or 5 GHz center frequencies calculated from primary and secondary channel numbers and sets a descriptor status field according to the requested event type.",
  "subsystem": "rf",
  "var_renames": {
    "result": "event_type",
    "a2": "primary_channel",
    "a3": "secondary_channel",
    "a4": "chan_desc",
    "v5": "secondary_center_freq_mhz",
    "v6": "center_freq_delta_mhz",
    "v8": "adjusted_center_freq_mhz"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "uint8 band (0=2.4 GHz, 1=5 GHz)"
    },
    {
      "offset": 1,
      "meaning": "uint8 channel status (set to 2, 3, or 4)"
    },
    {
      "offset": 2,
      "meaning": "uint16 auxiliary/previous center-frequency field used during type-2 adjustment"
    },
    {
      "offset": 4,
      "meaning": "uint16 center_freq1_mhz"
    },
    {
      "offset": 6,
      "meaning": "uint16 center_freq2_mhz"
    }
  ]
}
